/**
 * Every plugin tool name must be made only of lowercase letters, digits and
 * underscores (`[a-z0-9_]`).
 *
 * MCP hosts route tools/call by name and surface names in model prompts and
 * permission allow-lists. Uppercase letters, dashes, dots, spaces or other
 * symbols break exact-match allow-lists and some host name validators. The
 * catalog is generated by `bun run gen:tool-catalog` and committed as
 * servers/_tool-catalog.json; this test loads that file and fails on any name
 * outside the allowed shape. The checker is also exercised on synthetic input
 * so a regression in the checker itself cannot pass silently.
 */

import { describe, expect, test } from "bun:test";
import catalog from "../servers/_tool-catalog.json" with { type: "json" };

const TOOL_NAME_SHAPE = /^[a-z0-9_]+$/;

interface NamedTool {
  name: unknown;
}

/**
 * Describe each tool whose name is not a string or contains anything outside
 * `[a-z0-9_]`. Returns one line per problem, in catalog order.
 */
function invalidToolNames(tools: readonly NamedTool[]): string[] {
  return tools.flatMap((tool) => {
    if (typeof tool.name !== "string") {
      return [`${JSON.stringify(tool.name)}: name is not a string`];
    }
    if (!TOOL_NAME_SHAPE.test(tool.name)) {
      return [`${tool.name}: name must match ${TOOL_NAME_SHAPE}`];
    }
    return [];
  });
}

describe("plugin tool catalog names", () => {
  test("catalog is non-empty so the shape check cannot pass vacuously", () => {
    expect(catalog.length).toBeGreaterThan(0);
  });

  test("every tool name is lowercase letters, digits and underscores", () => {
    expect(invalidToolNames(catalog)).toEqual([]);
  });

  test("checker accepts valid names and reports bad ones", () => {
    expect(invalidToolNames([{ name: "ashlr__read" }, { name: "pipe2" }, { name: "_x" }])).toEqual([]);
    expect(invalidToolNames([{ name: "Read" }])).toEqual(["Read: name must match /^[a-z0-9_]+$/"]);
    expect(invalidToolNames([{ name: "ashlr-read" }])).toEqual([
      "ashlr-read: name must match /^[a-z0-9_]+$/",
    ]);
    expect(invalidToolNames([{ name: "ashlr.read" }, { name: "ashlr read" }])).toEqual([
      "ashlr.read: name must match /^[a-z0-9_]+$/",
      "ashlr read: name must match /^[a-z0-9_]+$/",
    ]);
    expect(invalidToolNames([{ name: "" }])).toEqual([": name must match /^[a-z0-9_]+$/"]);
    expect(invalidToolNames([{ name: 7 }, { name: undefined }])).toEqual([
      "7: name is not a string",
      "undefined: name is not a string",
    ]);
  });
});
